public static class StateProbes150{
 public static JsonElement[] Journal(bool b)=>Journal147.ReadComplete(Diagnosis150.Previous+"/native/"+(b?"separated149-autonomous":"baseline149-final148")+"-decisions.jsonl").Where(x=>x.GetProperty("Event").GetString()=="decision").ToArray();
 public static State146 State(JsonElement x)=>new(x.GetProperty("Observed").Deserialize<FreeRacingInput>(Program150.Json)!,x.GetProperty("CrankOmega").GetDouble());
 public static void Run(string label="",bool spatial=false,bool accepted=false,bool joint=false){using var budget=new Budget150("single-state-critical-and-heldout"+label,0,200);var summaries=new List<object>();
  foreach(var (model,time,role) in new[]{(false,28.4,"design-B"),(true,28.4,"design-B"),(true,45.8,"design-C"),(false,12.8,"heldout"),(true,39.4,"heldout")}){
   var path=Diagnosis150.Previous+"/native/"+(model?"separated149-autonomous":"baseline149-final148")+".json.gz";var native=Program150.Read<Run144>(path);var row=Journal(model).Single(x=>Math.Abs(x.GetProperty("Time").GetDouble()-time)<1e-6);var s=State(row);var planner=new Planner150(native.Riders[0].Spec,model,new(Enabled:true,Feedback:true,SpatialFeedback:spatial,AcceptedOperatingPoint:accepted,JointFeedback:joint),budget.Guard);string? failure=null;try{planner.Choose(s.Input,new(omega:s.CrankOmega));}catch(InvalidOperationException error){failure=error.Message;}
   var name=$"probe{label}-{(model?"B":"A")}-{time.ToString("0.0",System.Globalization.CultureInfo.InvariantCulture)}";Program150.Save(name+".json",new{Role=role,Model=model?"B":"A",Time=time,Failure=failure,Review=planner.Last});summaries.Add(new{Name=name,Failure=failure,planner.Last?.Reason,planner.Last?.Legal,planner.Last?.Robust});Console.WriteLine(name+": "+(failure??"certified"));
  }
  Program150.Save("state-probe"+label+"-summary.json",summaries);budget.Finish("design/held-out detached state probes complete");
 }
 public static void BaselineAudit(){using var budget=new Budget150("critical22-ranking-and-manual-space-audit",0,100);var rows=new List<object>();foreach(var model in new[]{false,true}){
  var native=Program150.Read<Run144>(Diagnosis150.Previous+"/native/"+(model?"separated149-autonomous":"baseline149-final148")+".json.gz");var journal=Journal(model);var previous=journal.Single(x=>Math.Abs(x.GetProperty("Time").GetDouble()-22.4)<1e-7);var now=journal.Single(x=>Math.Abs(x.GetProperty("Time").GetDouble()-22.6)<1e-7);var start=State(previous);var observed=State(now);var spec=native.Riders[0].Spec;var rt=new Runtime150(spec,model,false);rt.Begin(start.Input.Time);var actions=previous.GetProperty("PlannedActions").Deserialize<FreeRacingAction[]>(Program150.Json)!;var goal=previous.GetProperty("GoalMeters").GetDouble();var safety=previous.GetProperty("SafetyGoalMeters").GetDouble();var tape=Rollout150.Evaluate(rt,start,actions,goal,safety,"reconstructed-old",early:false,guard:budget.Guard);var oldPlan=new Plan146(start.Input.Time,goal,safety,actions,tape.Points,tape.End,previous.GetProperty("GoalTime").GetDouble(),previous.GetProperty("CornerExitTime").GetDouble(),previous.GetProperty("CornerExitSpeed").GetDouble(),tape.Safety,previous.GetProperty("Origin").GetString()!);var expected=rt.Step(start,actions[0]).End;
  var f=rt.Frame;var p=FreeLearningExperiment.Parameters();var surface=MultiActionExperiment135.Surface(f);var options=new RuntimeOptions147(EventSearch:true,WorkBudget:true,ProposalsPerThrottle:2,MaximumActualForecasts:8192,MaximumContacts:700000,OptionalSearchContacts:500000);var a=model?null:new ExactRuntime148(spec,f,surface,p,options);var b=model?new ExactRuntime149(spec,f,surface,p,options):null;if(model)b!.InitializeHistory(start.Input,oldPlan);else a!.InitializeHistory(start.Input,oldPlan);var planner=new Planner146(spec,f,surface,p,new(Enabled:true),budgetGuard:budget.Guard,hooks:model?b!.Hooks():a!.Hooks());planner.RestoreMemoryForDiagnostics(new(oldPlan,expected,23.6));var chosen=planner.Choose(observed.Input,new(omega:observed.CrankOmega));var exact=chosen.Choice.Action==now.GetProperty("Selected").Deserialize<FreeRacingAction>(Program150.Json);rows.Add(new{Model=model?"B":"A",ReconstructedChoiceMatches=exact,Chosen=chosen.Choice.Action,Review=planner.Reviews[^1]});Console.WriteLine("22.6 "+(model?"B":"A")+" exact="+exact);
  }
  Program150.Save("critical22-ranking.json.gz",rows);
  var manual=Program150.Read<JsonElement>(Diagnosis150.Previous+"/fixtures/causal-28.4-outward-B-result.json").GetProperty("Interventions")[0];var input=manual.GetProperty("Observed").Deserialize<FreeRacingInput>(Program150.Json)!;var root=manual.GetProperty("Unmodified").Deserialize<FreeRacingAction>(Program150.Json);var submitted=manual.GetProperty("Submitted").Deserialize<FreeRacingAction>(Program150.Json);var state=new State146(input,manual.GetProperty("CrankOmega").GetDouble());var grid=FreeLearningController.Actions(input,Controller143.Policy,true);var expanded=Planner150.DiverseActions(state,root);Program150.Save("manual-action-space.json",new{OriginalGridIncludes=grid.Contains(submitted),ExpandedRuleIncludes=expanded.Contains(submitted),OriginalGrid=grid,ExpandedRule=expanded,DiagnosticSubmitted=submitted,GeneratorRule="Original angles plus adjacent midpoints, throttle channels unchanged. No benchmark action or switch time read by planner.",GeometryGoal=Planner146.Goal(StandingWorld144.Frame(),input.Rider.TotalReferenceMeters,3)});budget.Finish("baseline complete plan ranks and action-space exclusion audit");
 }
